from inventory import add_item, average_qty


def test_add_item_counts():
    stock = {}
    add_item(stock, "bolt", 3)
    add_item(stock, "bolt", 2)
    assert stock["bolt"] == 5


def test_average_qty():
    assert average_qty({"a": 2, "b": 4}) == 3
